#!/usr/bin/env node
/**
 * ADR-166 §6 acceptance #9 — anti-regression lock for the MCP-bridge
 * security surface. Runs on the source of BOTH bridge files (the ruvocal
 * variant that ships in docker-compose, and the sibling REST bridge).
 *
 * Fails if any of the following load-bearing controls silently disappears:
 *   1. `MCP_BIND_HOST` default is `127.0.0.1` (loopback default — Phase 1a)
 *   2. Public bind without `MCP_AUTH_TOKEN` calls `process.exit(1)` at boot (Phase 1b)
 *   3. `requireAuth` middleware exists and is mounted with `app.use(requireAuth)` (Phase 1c)
 *   4. `requireAuth` uses `timingSafeEqual` (constant-time compare)
 *   5. `executeTool` denies terminal_execute unless `MCP_ENABLE_TERMINAL === "true"` (Phase 1d + 2a)
 *   6. CORS respects `MCP_CORS_ORIGIN` allowlist (Phase 3b)
 *   9. Both production images use the supported Node 24 LTS line (#2847)
 *
 * Runs offline (no server, no deps). CI-safe.
 *
 *   node test-security-lock.js       # → exit 0 on green, exit 1 on regression
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const BRIDGES = [
  path.join(HERE, "index.js"),                           // ruflo/src/mcp-bridge/index.js
  path.join(HERE, "..", "ruvocal", "mcp-bridge", "index.js"), // ruvocal variant (deployed)
];
const DOCKERFILES = [
  path.join(HERE, "Dockerfile"),
  path.join(HERE, "..", "ruvocal", "mcp-bridge", "Dockerfile"),
];

const CHECKS = [
  {
    id: "1. bind-loopback-default",
    rx: /BIND_HOST\s*=\s*process\.env\.MCP_BIND_HOST\s*\|\|\s*["']127\.0\.0\.1["']/,
    hint: "MCP_BIND_HOST must default to 127.0.0.1 (ADR-166 §6 Phase 1a)",
  },
  {
    id: "2. fail-closed-public-bind",
    rx: /isPublic\s*&&\s*!process\.env\.MCP_AUTH_TOKEN[\s\S]*?process\.exit\(\s*1\s*\)/,
    hint: "public bind without MCP_AUTH_TOKEN must process.exit(1) at boot (Phase 1b)",
  },
  {
    id: "3. auth-middleware-mounted",
    rx: /app\.use\(\s*requireAuth\s*\)/,
    hint: "requireAuth middleware must be mounted via app.use() (Phase 1c)",
  },
  {
    id: "4. constant-time-token-compare",
    rx: /timingSafeEqual\s*\(/,
    hint: "auth compare must use timingSafeEqual (Phase 1c)",
  },
  {
    id: "5. terminal-gate-server-side",
    rx: /MCP_ENABLE_TERMINAL[\s\S]*?executeTool[\s\S]*?TOOL_DISABLED|executeTool[\s\S]*?MCP_ENABLE_TERMINAL[\s\S]*?TOOL_DISABLED/,
    hint: "terminal_execute must be denied at executeTool unless MCP_ENABLE_TERMINAL=true (Phase 1d + 2a)",
  },
  {
    id: "6. cors-allowlist-respected",
    rx: /MCP_CORS_ORIGIN[\s\S]*?CORS_ALLOWLIST/,
    hint: "CORS must respect MCP_CORS_ORIGIN allowlist (Phase 3b)",
  },
  {
    id: "7. streamable-http-delete-handler (#2425)",
    rx: /app\.delete\(\s*["']\/mcp["']\s*,/,
    hint: "DELETE /mcp must be handled for streamable-HTTP session cleanup (#2425)",
  },
  {
    id: "8. mcp-session-id-header (#2425)",
    rx: /Mcp-Session-Id/,
    hint: "Mcp-Session-Id header must be echoed on /mcp* responses (#2425)",
  },
];

let hardFail = false;
for (const bridge of BRIDGES) {
  if (!fs.existsSync(bridge)) {
    console.error(`FAIL: bridge missing: ${bridge}`);
    hardFail = true;
    continue;
  }
  const src = fs.readFileSync(bridge, "utf-8");
  const rel = path.relative(path.join(HERE, "..", ".."), bridge);
  console.log(`\n# ${rel}`);
  for (const check of CHECKS) {
    if (check.rx.test(src)) {
      console.log(`  ✓ ${check.id}`);
    } else {
      console.log(`  ✗ ${check.id}`);
      console.log(`    hint: ${check.hint}`);
      hardFail = true;
    }
  }
}

for (const dockerfile of DOCKERFILES) {
  if (!fs.existsSync(dockerfile)) {
    console.error(`FAIL: Dockerfile missing: ${dockerfile}`);
    hardFail = true;
    continue;
  }
  const source = fs.readFileSync(dockerfile, "utf-8");
  const rel = path.relative(path.join(HERE, "..", ".."), dockerfile);
  console.log(`\n# ${rel}`);
  if (/^FROM\s+node:24(?:[.-][^\s]+)?\s*$/m.test(source)) {
    console.log("  ✓ 9. supported-node-lts-runtime (#2847)");
  } else {
    console.log("  ✗ 9. supported-node-lts-runtime (#2847)");
    console.log("    hint: production images must use the supported node:24 LTS line");
    hardFail = true;
  }
}

if (hardFail) {
  console.error("\nADR-166 security lock FAILED — a load-bearing control was removed or drifted.");
  process.exit(1);
}
console.log("\nADR-166 security lock: OK");

/**
 * @claude-flow/browser - Action Routing + GOAP Preflight Tests (ADR-122 Phase 5)
 *
 * Acceptance criteria covered:
 *  - ≥30% of typical browser actions classify as Tier 1 (Agent Booster, $0)
 *  - High causal risk escalates Tier 1 → Tier 2+
 *  - Per-trajectory cost report aggregates by tier + computes Tier-1 share
 *  - GOAP preflight catches missing-cookie precondition before live session
 *  - GOAP preflight catches unsafe-URL on `open` steps
 *  - GOAP preflight produces routing plan with estimated total cost
 */

import { describe, it, expect } from 'vitest';
import { ActionRouter } from '../src/application/action-router.js';
import { GoapPreflightService } from '../src/application/goap-preflight.js';
import { CookieVaultService } from '../src/application/cookie-vault-service.js';
import { CausalRecoveryService } from '../src/application/causal-recovery-service.js';

describe('ActionRouter', () => {
  describe('classification', () => {
    it('classifies pure DOM verbs with resolved refs as Tier 1', () => {
      const router = new ActionRouter();
      const decision = router.classify({ action: 'click', selector: '@e1', hasResolvedRef: true });
      expect(decision.tier).toBe('tier-1-booster');
      expect(decision.estimatedCostUsd).toBe(0);
      expect(decision.model).toBe('agent-booster');
    });

    it('classifies find verbs as Tier 2', () => {
      const router = new ActionRouter();
      expect(router.classify({ action: 'findByText', selector: 'Submit' }).tier).toBe('tier-2-haiku');
      expect(router.classify({ action: 'findByRole', selector: 'button' }).tier).toBe('tier-2-haiku');
    });

    it('escalates Tier 1 → Tier 2 when causal risk is high', () => {
      const router = new ActionRouter({ riskEscalationThreshold: 0.4 });
      const decision = router.classify({
        action: 'click',
        selector: '@e3',
        hasResolvedRef: true,
        causalRiskScore: 0.7,
      });
      expect(decision.tier).toBe('tier-2-haiku');
      expect(decision.rationale).toContain('causal risk');
    });

    it('classifies high-complexity hints as Tier 3', () => {
      const router = new ActionRouter();
      const decision = router.classify({ action: 'click', complexity: 'high' });
      expect(decision.tier).toBe('tier-3-frontier');
    });

    it('classifies eval as Tier 3', () => {
      const router = new ActionRouter();
      expect(router.classify({ action: 'eval' }).tier).toBe('tier-3-frontier');
    });
  });

  describe('cost rollup', () => {
    it('aggregates per-trajectory cost by tier', () => {
      const router = new ActionRouter();
      const trajectoryId = 'traj-1';
      // 3 Tier 1, 1 Tier 2, 1 Tier 3
      router.record(trajectoryId, router.classify({ action: 'click', selector: '@e1', hasResolvedRef: true }));
      router.record(trajectoryId, router.classify({ action: 'fill', selector: '@e2', hasResolvedRef: true }));
      router.record(trajectoryId, router.classify({ action: 'click', selector: '@e3', hasResolvedRef: true }));
      router.record(trajectoryId, router.classify({ action: 'findByText', selector: 'Submit' }));
      router.record(trajectoryId, router.classify({ action: 'eval' }));

      const report = router.getCostReport(trajectoryId);
      expect(report).toBeDefined();
      expect(report!.byTier['tier-1-booster'].count).toBe(3);
      expect(report!.byTier['tier-2-haiku'].count).toBe(1);
      expect(report!.byTier['tier-3-frontier'].count).toBe(1);
      expect(report!.totalCostUsd).toBeCloseTo(0 + 0 + 0 + 0.0002 + 0.005, 5);
      expect(report!.tier1Share).toBeCloseTo(3 / 5, 2);
    });

    it('representative workload achieves ≥30% Tier-1 share', () => {
      const router = new ActionRouter();
      const trajectoryId = 'traj-rep';
      // Typical login flow: open + snapshot + fill + fill + click → 4 pure DOM, 1 navigation
      const actions = [
        { action: 'open', selector: 'https://example.com' },
        { action: 'snapshot' as const },
        { action: 'fill', selector: '@e1', hasResolvedRef: true },
        { action: 'fill', selector: '@e2', hasResolvedRef: true },
        { action: 'click', selector: '@e3', hasResolvedRef: true },
        { action: 'wait', selector: '.dashboard' },
        { action: 'getText', selector: '.welcome' },
      ];
      for (const a of actions) router.record(trajectoryId, router.classify(a as { action: string; selector?: string; hasResolvedRef?: boolean }));
      const report = router.getCostReport(trajectoryId)!;
      expect(report.tier1Share).toBeGreaterThanOrEqual(0.3);
    });
  });
});

describe('GoapPreflightService', () => {
  it('passes preflight when all preconditions are met', async () => {
    const vault = new CookieVaultService();
    await vault.store({
      cookie: { name: 'sid', value: 'opaque-token', domain: 'example.com' },
      origin: 'https://example.com',
    });
    const preflight = new GoapPreflightService({ cookieVault: vault });

    const result = await preflight.preflight({
      goal: 'View dashboard',
      origin: 'https://example.com',
      steps: [
        {
          action: 'open',
          target: 'https://example.com/dashboard',
          preconditions: { requireCookie: { origin: 'https://example.com', name: 'sid' } },
        },
        { action: 'click', target: '@e1' },
      ],
    });

    expect(result.ok).toBe(true);
    expect(result.findings.filter(f => f.blocking)).toHaveLength(0);
    expect(result.routingPlan).toHaveLength(2);
    expect(result.estimatedCostUsd).toBeGreaterThanOrEqual(0);
  });

  it('blocks when a required cookie is missing from the vault', async () => {
    const vault = new CookieVaultService();
    const preflight = new GoapPreflightService({ cookieVault: vault });

    const result = await preflight.preflight({
      goal: 'View dashboard',
      steps: [
        {
          action: 'open',
          target: 'https://example.com/dashboard',
          preconditions: { requireCookie: { origin: 'https://example.com', name: 'sid' } },
        },
      ],
    });

    expect(result.ok).toBe(false);
    const missing = result.findings.find(f => f.kind === 'missing-cookie');
    expect(missing).toBeDefined();
    expect(missing!.blocking).toBe(true);
  });

  it('warns (non-blocking) when origin has high causal risk', async () => {
    const causal = new CausalRecoveryService();
    for (let i = 0; i < 12; i++) {
      await causal.reportBreak({
        url: 'https://example.com/login',
        selector: '@e3',
        action: 'click',
        actionResult: { success: false, error: 'not found' },
      });
    }
    const preflight = new GoapPreflightService({ causalService: causal });

    const result = await preflight.preflight({
      goal: 'Click submit',
      origin: 'https://example.com',
      steps: [
        {
          action: 'click',
          target: '@e3',
          preconditions: { maxAvgCausalRisk: 0.5 },
        },
      ],
    });

    const warning = result.findings.find(f => f.kind === 'high-causal-risk');
    expect(warning).toBeDefined();
    expect(warning!.blocking).toBe(false);
    // ok stays true because high-causal-risk is non-blocking by design
    expect(result.ok).toBe(true);
  });

  it('produces a routing plan with per-step decisions + total cost', async () => {
    const preflight = new GoapPreflightService();
    const result = await preflight.preflight({
      goal: 'Compose login',
      steps: [
        { action: 'open', target: 'https://example.com' },
        { action: 'fill', target: '@e1', routing: { action: 'fill', selector: '@e1', hasResolvedRef: true } },
        { action: 'findByText', target: 'Sign in', routing: { action: 'findByText', selector: 'Sign in' } },
      ],
    });

    expect(result.routingPlan).toHaveLength(3);
    const tiers = result.routingPlan.map(p => p.decision.tier);
    expect(tiers).toContain('tier-1-booster'); // fill with ref
    expect(tiers).toContain('tier-2-haiku'); // findByText
    expect(result.estimatedCostUsd).toBeGreaterThan(0);
  });
});

import { describe, expect, it } from 'vitest';
import { browserCommand } from '../src/oauth/browser.js';

describe('OAuth browser launcher', () => {
  it('preserves the complete OAuth query string on Windows without cmd.exe', () => {
    const url = 'https://auth.cognitum.one/oauth/authorize?response_type=code&client_id=meta-proxy&state=test';
    const launch = browserCommand(url, 'win32');

    expect(launch.cmd).toBe('rundll32.exe');
    expect(launch.args).toEqual(['url.dll,FileProtocolHandler', url]);
    expect(launch.args[1]).toContain('&client_id=meta-proxy&');
  });
});

/**
 * @claude-flow/browser - Security Integration Tests
 */

import { describe, it, expect, beforeEach } from 'vitest';
import {
  BrowserSecurityScanner,
  getSecurityScanner,
  isUrlSafe,
  containsPII,
  type SecurityConfig,
} from '../src/infrastructure/security-integration.js';

describe('BrowserSecurityScanner', () => {
  let scanner: BrowserSecurityScanner;

  beforeEach(() => {
    scanner = new BrowserSecurityScanner();
  });

  describe('scanUrl', () => {
    it('should pass safe HTTPS URLs', async () => {
      const result = await scanner.scanUrl('https://example.com');
      expect(result.safe).toBe(true);
      expect(result.score).toBeGreaterThan(0.7);
    });

    it('should warn about HTTP URLs when requireHttps is enabled', async () => {
      const strictScanner = new BrowserSecurityScanner({ requireHttps: true });
      const result = await strictScanner.scanUrl('http://example.com');
      expect(result.threats.some(t => t.type === 'insecure-protocol')).toBe(true);
    });

    it('should detect blocked domains', async () => {
      const result = await scanner.scanUrl('https://bit.ly/abcd123');
      expect(result.threats.some(t => t.type === 'blocked-domain')).toBe(true);
    });

    it('should detect suspicious TLDs', async () => {
      const result = await scanner.scanUrl('https://suspicious-site.xyz');
      expect(result.threats.some(t => t.type === 'phishing')).toBe(true);
    });

    it('should detect IP address URLs', async () => {
      const result = await scanner.scanUrl('https://192.168.1.1/login');
      expect(result.threats.some(t => t.type === 'suspicious-redirect')).toBe(true);
    });

    it('should detect phishing indicators in URL', async () => {
      const result = await scanner.scanUrl('https://secure-login-verify.example.com');
      expect(result.threats.some(t => t.type === 'phishing')).toBe(true);
    });

    it('should allow domains in allowedDomains list', async () => {
      const allowedScanner = new BrowserSecurityScanner({
        allowedDomains: ['bit.ly'],
      });
      const result = await allowedScanner.scanUrl('https://bit.ly/safe');
      expect(result.threats.some(t => t.type === 'blocked-domain')).toBe(false);
    });
  });

  describe('scanContent', () => {
    it('should detect email addresses', () => {
      const result = scanner.scanContent('Contact us at test@example.com for help');
      expect(result.pii.some(p => p.type === 'email')).toBe(true);
    });

    it('should detect phone numbers', () => {
      const result = scanner.scanContent('Call us at 555-123-4567');
      expect(result.pii.some(p => p.type === 'phone')).toBe(true);
    });

    it('should detect SSNs', () => {
      const result = scanner.scanContent('SSN: 123-45-6789');
      expect(result.pii.some(p => p.type === 'ssn')).toBe(true);
    });

    it('should detect credit card numbers', () => {
      const result = scanner.scanContent('Card: 4111-1111-1111-1111');
      expect(result.pii.some(p => p.type === 'credit-card')).toBe(true);
    });

    it('should detect API keys', () => {
      // API key pattern: sk- or sk_ followed by 20+ alphanumeric chars
      const result = scanner.scanContent('API Key: sk_abcdefghij1234567890abc');
      expect(result.pii.some(p => p.type === 'api-key')).toBe(true);
    });

    it('should add threat for sensitive PII', () => {
      const result = scanner.scanContent('SSN: 123-45-6789, Card: 4111-1111-1111-1111');
      expect(result.threats.some(t => t.type === 'data-exfiltration')).toBe(true);
    });

    it('should return safe for content without PII', () => {
      const result = scanner.scanContent('This is just regular text content');
      expect(result.pii.length).toBe(0);
      expect(result.safe).toBe(true);
    });
  });

  describe('validateInput', () => {
    it('should detect SQL injection patterns', () => {
      const result = scanner.validateInput("'; DROP TABLE users; --", 'username');
      expect(result.threats.some(t => t.type === 'injection')).toBe(true);
    });

    it('should detect XSS patterns', () => {
      const result = scanner.validateInput('<script>alert("xss")</script>', 'comment');
      expect(result.threats.some(t => t.type === 'xss')).toBe(true);
    });

    it('should detect event handler XSS', () => {
      const result = scanner.validateInput('<img src="x" onerror="alert(1)">', 'bio');
      expect(result.threats.some(t => t.type === 'xss')).toBe(true);
    });

    it('should pass safe input', () => {
      const result = scanner.validateInput('Hello, World!', 'message');
      expect(result.safe).toBe(true);
    });
  });

  describe('sanitizeInput', () => {
    it('should escape HTML entities', () => {
      const result = scanner.sanitizeInput('<script>alert("xss")</script>');
      expect(result).not.toContain('<script>');
      expect(result).toContain('&lt;');
      expect(result).toContain('&gt;');
    });

    it('should remove script tags', () => {
      const result = scanner.sanitizeInput('Hello <script>evil()</script> World');
      expect(result).not.toContain('<script>');
    });

    it('should escape HTML entities', () => {
      const result = scanner.sanitizeInput('<div onclick="evil()">click me</div>');
      // The sanitizer escapes HTML entities (which also neutralizes event handlers)
      expect(result).toContain('&lt;div');
      expect(result).toContain('&gt;');
    });
  });

  describe('maskPII', () => {
    it('should mask email addresses', () => {
      const result = scanner.maskPII('test@example.com', 'email');
      expect(result).toMatch(/t\*+@example\.com/);
    });

    it('should mask phone numbers', () => {
      const result = scanner.maskPII('5551234567', 'phone');
      // The phone masking leaves the last 4 digits visible
      expect(result.endsWith('4567')).toBe(true);
    });

    it('should mask SSNs', () => {
      const result = scanner.maskPII('123-45-6789', 'ssn');
      expect(result).toBe('***-**-6789');
    });

    it('should mask credit card numbers', () => {
      const result = scanner.maskPII('4111111111111111', 'credit-card');
      expect(result).toMatch(/\*+ 1111$/);
    });

    it('should mask API keys', () => {
      const result = scanner.maskPII('sk_live_1234567890abcdefghij', 'api-key');
      expect(result).toMatch(/^sk_live_\*+/);
    });

    it('should completely mask passwords', () => {
      const result = scanner.maskPII('secretpassword', 'password');
      expect(result).toBe('********');
    });
  });
});

describe('factory functions', () => {
  it('getSecurityScanner should return scanner', () => {
    const scanner = getSecurityScanner();
    expect(scanner).toBeInstanceOf(BrowserSecurityScanner);
  });

  it('isUrlSafe should return boolean', async () => {
    const result = await isUrlSafe('https://example.com');
    expect(typeof result).toBe('boolean');
  });

  it('containsPII should detect PII', () => {
    expect(containsPII('My email is test@example.com')).toBe(true);
    expect(containsPII('Hello World')).toBe(false);
  });
});

import { describe, expect, it } from 'vitest';
import {
  AgenticPolicyEngine,
  checkCapabilityEnvelope,
  createLegacyCompatibleState,
  delegateEnvelope,
  isEnvelopeReduction,
  type PolicyRequest,
  type PolicyRule,
} from '../src/policy/index.js';

const request = (overrides: Partial<PolicyRequest> = {}): PolicyRequest => ({
  identity: { id: 'agent:coder', type: 'agent', roles: ['developer'] },
  action: { type: 'code.write', resource: 'src/app.ts', environment: 'development' },
  ...overrides,
});

describe('AgenticPolicyEngine', () => {
  it('preserves existing installations in legacy mode', () => {
    const engine = AgenticPolicyEngine.fromState(createLegacyCompatibleState());
    const decision = engine.evaluate(request());
    expect(decision.outcome).toBe('allowed');
    expect(decision.enforcedOutcome).toBe('allowed');
    expect(decision.reason).toBe('legacy-default-allow');
  });

  it('observes default deny without breaking the action', () => {
    const engine = new AgenticPolicyEngine({ mode: 'observe' });
    const decision = engine.evaluate(request());
    expect(decision.outcome).toBe('denied');
    expect(decision.enforcedOutcome).toBe('allowed');
  });

  it('enforces default deny and deny-overrides', () => {
    const rules: PolicyRule[] = [
      { id: 'allow-code', effect: 'allow', actions: ['code.*'] },
      { id: 'deny-production', effect: 'deny', actions: ['code.write'], environments: ['production'], priority: 10 },
    ];
    const engine = new AgenticPolicyEngine({ mode: 'enforce', rules });
    expect(engine.evaluate(request()).enforcedOutcome).toBe('allowed');
    expect(engine.evaluate(request({
      action: { type: 'code.write', resource: 'src/app.ts', environment: 'production' },
    })).enforcedOutcome).toBe('denied');
  });

  it('requires signed tool evidence when a rule asks for it', () => {
    const engine = new AgenticPolicyEngine({
      mode: 'enforce',
      evidenceVerifier: (evidence) => evidence.signature === 'valid-test-signature',
      rules: [{
        id: 'verified-deploy',
        effect: 'allow',
        actions: ['deployment.promote'],
        constraints: { requireSignedEvidence: true, requiredProvenance: ['tool_result'] },
      }],
    });
    const base = request({ action: { type: 'deployment.promote', environment: 'production' } });
    expect(engine.evaluate(base).enforcedOutcome).toBe('denied');
    expect(engine.evaluate({
      ...base,
      context: { evidence: [{
        id: 'evidence-1',
        provenance: 'tool_result',
        signed: true,
        signature: 'valid-test-signature',
      }] },
    }).enforcedOutcome).toBe('allowed');
    expect(engine.evaluate({
      ...base,
      context: { evidence: [{ id: 'fake', provenance: 'tool_result', signed: true }] },
    }).enforcedOutcome).toBe('denied');
    expect(engine.evaluate({
      ...base,
      context: {
        evidence: [
          { id: 'verified-wrong-type', provenance: 'user_claim', signature: 'valid-test-signature' },
          { id: 'unsigned-right-type', provenance: 'tool_result' },
        ],
      },
    }).enforcedOutcome).toBe('denied');
  });

  it('requires a scoped human approval and forbids self approval', () => {
    const engine = new AgenticPolicyEngine({
      mode: 'enforce',
      now: () => 1_000,
      approvalIssuerVerifier: (issuer) => issuer === 'user:release-manager',
      rules: [{ id: 'prod-approval', effect: 'require_approval', actions: ['deployment.promote'] }],
    });
    expect(() => engine.issueApproval({
      id: 'self',
      principal: 'agent:coder',
      actions: ['deployment.promote'],
      issuedBy: 'agent:coder',
      expiresAt: 2_000,
      maxUses: 2,
    })).toThrow('self-approval-forbidden');
    engine.issueApproval({
      id: 'human-1',
      principal: 'agent:coder',
      actions: ['deployment.promote'],
      issuedBy: 'user:release-manager',
      expiresAt: 2_000,
      maxUses: 1,
    });
    const deploy = request({
      action: { type: 'deployment.promote', resource: 'prod' },
      context: { approvalIds: ['human-1'], now: 1_100 },
    });
    expect(engine.evaluate(deploy).reason).toBe('approved-by:human-1');
    expect(engine.evaluate(deploy).enforcedOutcome).toBe('approval_required');
  });

  it('uses authority time and rejects ambiguous approval accounting', () => {
    let authorityNow = 2_000;
    const engine = new AgenticPolicyEngine({
      mode: 'enforce',
      now: () => authorityNow,
      approvalIssuerVerifier: () => true,
      rules: [{ id: 'approval', effect: 'require_approval', actions: ['deploy'] }],
    });
    engine.issueApproval({
      id: 'approval-1',
      principal: 'agent:coder',
      actions: ['deploy'],
      issuedBy: 'user:admin',
      issuedAt: 1_000,
      expiresAt: 3_000,
      maxUses: 1,
    });
    expect(() => engine.issueApproval({
      id: 'approval-1',
      principal: 'agent:coder',
      actions: ['deploy'],
      issuedBy: 'user:admin',
      issuedAt: 1_000,
      expiresAt: 3_000,
      maxUses: 1,
    })).toThrow('duplicate-approval-id');
    expect(() => engine.issueApproval({
      id: 'bad-uses',
      principal: 'agent:coder',
      actions: ['deploy'],
      issuedBy: 'user:admin',
      issuedAt: 1_000,
      expiresAt: 3_000,
      maxUses: 1,
      uses: -1,
    })).toThrow('invalid-approval');
    expect(engine.evaluate(request({
      action: { type: 'deploy' },
      context: { approvalIds: ['approval-1'], now: 0 },
    })).enforcedOutcome).toBe('allowed');
    authorityNow = 4_000;
    expect(engine.evaluate(request({
      action: { type: 'deploy' },
      context: { approvalIds: ['approval-1'], now: 0 },
    })).enforcedOutcome).toBe('approval_required');
  });

  it('atomically accounts budget usage', () => {
    const engine = new AgenticPolicyEngine({
      mode: 'enforce',
      now: () => 10,
      rules: [{ id: 'allow-model', effect: 'allow', actions: ['model.call'] }],
      budgets: [{ id: 'daily', principal: 'agent:*', action: 'model.call', maxCostUsd: 1, periodMs: 86_400_000 }],
    });
    const call = request({
      action: { type: 'model.call', resource: 'openrouter', costUsd: 0.6 },
    });
    expect(engine.evaluate(call).enforcedOutcome).toBe('allowed');
    expect(engine.evaluate(call).reason).toBe('budget-exceeded:daily');
  });

  it('creates and verifies a tamper-evident receipt chain', () => {
    const engine = new AgenticPolicyEngine({ mode: 'legacy', signingKey: 'test-secret' });
    engine.evaluate(request());
    engine.evaluate(request({ action: { type: 'code.read', resource: 'README.md' } }));
    expect(engine.verifyLedger()).toEqual({ valid: true, length: 2 });

    const state = engine.exportState();
    state.receipts[0]!.payload.decision.reason = 'tampered';
    const tampered = AgenticPolicyEngine.fromState(state, { signingKey: 'test-secret' });
    expect(tampered.verifyLedger().valid).toBe(false);
  });

  it('requires configured receipt authentication in both directions', () => {
    const signed = new AgenticPolicyEngine({ mode: 'legacy', signingKey: 'test-secret' });
    signed.evaluate(request());
    const strippedState = signed.exportState();
    delete strippedState.receipts[0]!.signature;
    expect(AgenticPolicyEngine.fromState(strippedState, { signingKey: 'test-secret' }).verifyLedger().error)
      .toBe('receipt-signature-missing');

    const signedState = signed.exportState();
    expect(AgenticPolicyEngine.fromState(signedState).verifyLedger().error)
      .toBe('receipt-signing-key-required');
  });

  it('rejects negative and non-finite resource accounting', () => {
    const engine = new AgenticPolicyEngine({ mode: 'legacy' });
    expect(() => engine.evaluate(request({
      action: { type: 'model.call', costUsd: -1 },
    }))).toThrow('invalid-policy-action-costUsd');
    expect(() => engine.evaluate(request({
